import { copyText } from '@/utils';
import { IconCheck, IconCopy } from '@arco-design/web-react/icon';
import { ReactNode, useEffect, useMemo, useState,} from 'react';
import hljs from 'highlight.js/lib/common';
import 'highlight.js/styles/atom-one-dark.css';
import { Button, Space, ButtonProps } from '@arco-design/web-react';


export interface HljsProps extends React.HTMLProps<HTMLDivElement>{
    code?: "CSS" | "JavaScript" | 'TypeScript' | "JSON" | "Less" | "HTML" | "XML",
    extra?: ReactNode,
    buttons?: ButtonProps[];
    hiddenHeader?: boolean;
    children: string;
    preProps?: React.HTMLProps<HTMLPreElement>;
}

function Hljs ({
    code,
    title,
    extra,
    buttons,
    hiddenHeader,
    children,
    preProps,
    ...props
}: HljsProps){

    const html = useMemo(() => {
        if(!children) return '<span />'
        return hljs.highlight(code.toLowerCase(), children.replace(/\t/g, '  ')).value
    },[children])

    const [successed, setSuccessed] = useState<boolean>(false);

    useEffect(() => {
        if(successed){
            setTimeout(() => {
                setSuccessed(false)
            },5000)
        }
    },[successed])

    return (
        <div className="hljs-component rounded-md flex-col" {...props}>
            {!hiddenHeader && (
                <div className="hljs-header items-center-between px-4 py-2 text-xs">
                    <div>
                        {title || code}
                    </div>
                    <Space>
                        {successed ? (
                            <div className="items-center">
                                <IconCheck />
                                <div style={{ marginLeft: 10 }}
                                >Copied!</div>
                            </div>
                        ):(
                            <div className="items-center" style={{ cursor: 'pointer' }}
                                onClick={() => {
                                    copyText(children).then(() => {
                                        setSuccessed(true)
                                    })
                                }}
                            >
                                <IconCopy />
                                <div style={{ marginLeft: 10 }}
                                >Copy code</div>
                            </div>
                        )}
                        {Boolean(buttons) && buttons.map((o, i) => {
                            return (<Button key={i} {...o} />)
                        })}
                        {extra}
                    </Space>
                </div>
            )}
            <pre 
                className="hljs p-4 overflow-auto"
                dangerouslySetInnerHTML={{ __html: html }}
                {...preProps}
            />
        </div>
    )
}

Hljs.defaultProps = {
    code: "JSON"
}

export default Hljs;